class Calculator:
    """
    This is a class for a calculator, capable of performing basic arithmetic calculations on numerical expressions
    using the operators +, -, *, /, and ^ (exponentiation).
    """

    def __init__(self):
        """
        Initialize the operations performed by the five operators '+', '-', '*', '/', '^'
        """
        self.operators = {
            '+': lambda x, y: x + y,
            '-': lambda x, y: x - y,
            '*': lambda x, y: x * y,
            '/': lambda x, y: x / y,
            '^': lambda x, y: x ** y
        }

    def calculate(self, expression):
        """
        Calculate the value of a given expression
        :param expression: string, given expression
        :return: If successful, returns the value of the expression; otherwise, returns None
        >>> calculator = Calculator()
        >>> calculator.calculate('1+2-3')
        0.0
        """
        if not isinstance(expression, str) or not expression.strip():
            return None

        operand_stack = []
        operator_stack = []
        num_buffer = ''
        i = 0
        length = len(expression)

        while i < length:
            char = expression[i]

            # Skip whitespace
            if char.isspace():
                i += 1
                continue

            # Number (digit or decimal point)
            if char.isdigit() or char == '.':
                num_buffer += char

            # Unary minus handling
            elif char == '-' and not num_buffer and (
                not operand_stack or
                (operator_stack and operator_stack[-1] in '+-*/^(')
            ):
                num_buffer += char

            # Binary operators
            elif char in '+-*/^':
                if num_buffer:
                    try:
                        operand_stack.append(float(num_buffer))
                    except ValueError:
                        return None
                    num_buffer = ''

                # Resolve operator precedence
                while (
                    operator_stack
                    and operator_stack[-1] != '('
                    and self.precedence(operator_stack[-1]) >= self.precedence(char)
                ):
                    try:
                        operand_stack, operator_stack = self.apply_operator(
                            operand_stack, operator_stack
                        )
                    except Exception:
                        return None

                operator_stack.append(char)

            # Left parenthesis
            elif char == '(':
                operator_stack.append(char)

            # Right parenthesis
            elif char == ')':
                if num_buffer:
                    try:
                        operand_stack.append(float(num_buffer))
                    except ValueError:
                        return None
                    num_buffer = ''

                while operator_stack and operator_stack[-1] != '(':
                    try:
                        operand_stack, operator_stack = self.apply_operator(
                            operand_stack, operator_stack
                        )
                    except Exception:
                        return None

                if not operator_stack or operator_stack[-1] != '(':
                    return None  # mismatched parentheses
                operator_stack.pop()  # Remove '('

            else:
                # Invalid character
                return None

            i += 1

        # Append any remaining number
        if num_buffer:
            try:
                operand_stack.append(float(num_buffer))
            except ValueError:
                return None

        # Apply remaining operators
        while operator_stack:
            if operator_stack[-1] in '()':
                return None  # mismatched parentheses
            try:
                operand_stack, operator_stack = self.apply_operator(
                    operand_stack, operator_stack
                )
            except Exception:
                return None

        # Final result
        if len(operand_stack) != 1:
            return None
        return operand_stack[0]

    def precedence(self, operator):
        """
        Returns the priority of the specified operator, where the higher the priority, the greater the assignment.
        The priority of '^' is greater than '/' and '*', and the priority of '/' and '*' is greater than '+' and '-'
        :param operator: string, given operator
        :return: int, the priority of the given operator, otherwise return 0
        >>> calculator = Calculator()
        >>> calculator.precedence('+')
        1
        >>> calculator.precedence('^')
        3
        """
        return {'+': 1, '-': 1, '*': 2, '/': 2, '^': 3}.get(operator, 0)

    def apply_operator(self, operand_stack, operator_stack):
        """
        Use the operator at the top of the operator stack to perform the operation on the two numbers at the top
        of the operand stack, and store the result at the top of the operand stack.
        :param operand_stack: list of operands
        :param operator_stack: list of operators
        :return: the updated operand_stack and operator_stack
        >>> calculator = Calculator()
        >>> calculator.apply_operator([1, 2, 3], ['+', '-'])
        ([1, -1], ['-'])
        """
        if not operator_stack:
            raise ValueError("Operator stack is empty")

        operator = operator_stack.pop()
        if operator not in self.operators:
            raise ValueError(f"Unknown operator: {operator}")

        if len(operand_stack) < 2:
            raise ValueError("Insufficient operands")

        operand2 = operand_stack.pop()
        operand1 = operand_stack.pop()

        try:
            result = self.operators[operator](operand1, operand2)
        except ZeroDivisionError:
            raise ZeroDivisionError("Division by zero")

        operand_stack.append(result)
        return operand_stack, operator_stack
